-- 032_strength_waves.sql
-- A ready-made program with loads as a percentage of the estimated 1RM:
-- "Strength Waves", four weeks on squat, bench press and deadlift, rising
-- from 70-80 % to 80-90 %, then a deload week at 60 %. In the three
-- languages. The percentages live in the program's structure ("percents"),
-- so no column is added.
--
-- Safe to re-run. All-or-nothing: wrapped in one transaction.

BEGIN;

INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
SELECT 'Vagues de force (% du 1RM)', 'Quatre semaines sur les trois grands mouvements, avec des charges en pourcentage de votre 1RM estimé : on monte de 70-80 % à 80-90 %, puis une semaine de décharge à 60 %. Recommencez ensuite avec un 1RM plus haut.', 'strength', 'intermediate', 3, false, '[{"name":"S1 · Squat","week":1,"exercises":[{"exerciseName":"Back Squat","targetSets":3,"targetReps":"5","restSec":180,"percents":[70,75,80]},{"exerciseName":"Romanian Deadlift","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Plank","targetSets":3,"targetReps":"30-45s","restSec":60}]},{"name":"S1 · Développé couché","week":1,"exercises":[{"exerciseName":"Barbell Bench Press","targetSets":3,"targetReps":"5","restSec":180,"percents":[70,75,80]},{"exerciseName":"Barbell Row","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Face Pull","targetSets":3,"targetReps":"15-20","restSec":60}]},{"name":"S1 · Soulevé de terre","week":1,"exercises":[{"exerciseName":"Deadlift","targetSets":3,"targetReps":"5","restSec":210,"percents":[70,75,80]},{"exerciseName":"Overhead Press","targetSets":3,"targetReps":"5","restSec":180,"percents":[70,75,80]},{"exerciseName":"Pull-up","targetSets":3,"targetReps":"5-8","restSec":120}]},{"name":"S2 · Squat","week":2,"exercises":[{"exerciseName":"Back Squat","targetSets":3,"targetReps":"4","restSec":180,"percents":[75,80,85]},{"exerciseName":"Romanian Deadlift","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Plank","targetSets":3,"targetReps":"30-45s","restSec":60}]},{"name":"S2 · Développé couché","week":2,"exercises":[{"exerciseName":"Barbell Bench Press","targetSets":3,"targetReps":"4","restSec":180,"percents":[75,80,85]},{"exerciseName":"Barbell Row","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Face Pull","targetSets":3,"targetReps":"15-20","restSec":60}]},{"name":"S2 · Soulevé de terre","week":2,"exercises":[{"exerciseName":"Deadlift","targetSets":3,"targetReps":"4","restSec":210,"percents":[75,80,85]},{"exerciseName":"Overhead Press","targetSets":3,"targetReps":"4","restSec":180,"percents":[75,80,85]},{"exerciseName":"Pull-up","targetSets":3,"targetReps":"5-8","restSec":120}]},{"name":"S3 · Squat","week":3,"exercises":[{"exerciseName":"Back Squat","targetSets":3,"targetReps":"3","restSec":180,"percents":[80,85,90]},{"exerciseName":"Romanian Deadlift","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Plank","targetSets":3,"targetReps":"30-45s","restSec":60}]},{"name":"S3 · Développé couché","week":3,"exercises":[{"exerciseName":"Barbell Bench Press","targetSets":3,"targetReps":"3","restSec":180,"percents":[80,85,90]},{"exerciseName":"Barbell Row","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Face Pull","targetSets":3,"targetReps":"15-20","restSec":60}]},{"name":"S3 · Soulevé de terre","week":3,"exercises":[{"exerciseName":"Deadlift","targetSets":3,"targetReps":"3","restSec":210,"percents":[80,85,90]},{"exerciseName":"Overhead Press","targetSets":3,"targetReps":"3","restSec":180,"percents":[80,85,90]},{"exerciseName":"Pull-up","targetSets":3,"targetReps":"5-8","restSec":120}]},{"name":"S4 · Squat (décharge)","week":4,"exercises":[{"exerciseName":"Back Squat","targetSets":3,"targetReps":"5","restSec":180,"percents":[60]},{"exerciseName":"Romanian Deadlift","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Plank","targetSets":3,"targetReps":"30-45s","restSec":60}]},{"name":"S4 · Développé couché (décharge)","week":4,"exercises":[{"exerciseName":"Barbell Bench Press","targetSets":3,"targetReps":"5","restSec":180,"percents":[60]},{"exerciseName":"Barbell Row","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Face Pull","targetSets":3,"targetReps":"15-20","restSec":60}]},{"name":"S4 · Soulevé de terre (décharge)","week":4,"exercises":[{"exerciseName":"Deadlift","targetSets":3,"targetReps":"5","restSec":210,"percents":[60]},{"exerciseName":"Overhead Press","targetSets":3,"targetReps":"5","restSec":180,"percents":[60]},{"exerciseName":"Pull-up","targetSets":3,"targetReps":"5-8","restSec":120}]}]'::jsonb, true, 140, 'fr'
WHERE NOT EXISTS (SELECT 1 FROM program_templates WHERE name = 'Vagues de force (% du 1RM)' AND locale = 'fr');

INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
SELECT 'Strength Waves (% of 1RM)', 'Four weeks on the three big lifts, with loads as a percentage of your estimated 1RM: from 70-80% up to 80-90%, then a deload week at 60%. Then start again with a higher 1RM.', 'strength', 'intermediate', 3, false, '[{"name":"W1 · Squat","week":1,"exercises":[{"exerciseName":"Back Squat","targetSets":3,"targetReps":"5","restSec":180,"percents":[70,75,80]},{"exerciseName":"Romanian Deadlift","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Plank","targetSets":3,"targetReps":"30-45s","restSec":60}]},{"name":"W1 · Bench press","week":1,"exercises":[{"exerciseName":"Barbell Bench Press","targetSets":3,"targetReps":"5","restSec":180,"percents":[70,75,80]},{"exerciseName":"Barbell Row","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Face Pull","targetSets":3,"targetReps":"15-20","restSec":60}]},{"name":"W1 · Deadlift","week":1,"exercises":[{"exerciseName":"Deadlift","targetSets":3,"targetReps":"5","restSec":210,"percents":[70,75,80]},{"exerciseName":"Overhead Press","targetSets":3,"targetReps":"5","restSec":180,"percents":[70,75,80]},{"exerciseName":"Pull-up","targetSets":3,"targetReps":"5-8","restSec":120}]},{"name":"W2 · Squat","week":2,"exercises":[{"exerciseName":"Back Squat","targetSets":3,"targetReps":"4","restSec":180,"percents":[75,80,85]},{"exerciseName":"Romanian Deadlift","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Plank","targetSets":3,"targetReps":"30-45s","restSec":60}]},{"name":"W2 · Bench press","week":2,"exercises":[{"exerciseName":"Barbell Bench Press","targetSets":3,"targetReps":"4","restSec":180,"percents":[75,80,85]},{"exerciseName":"Barbell Row","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Face Pull","targetSets":3,"targetReps":"15-20","restSec":60}]},{"name":"W2 · Deadlift","week":2,"exercises":[{"exerciseName":"Deadlift","targetSets":3,"targetReps":"4","restSec":210,"percents":[75,80,85]},{"exerciseName":"Overhead Press","targetSets":3,"targetReps":"4","restSec":180,"percents":[75,80,85]},{"exerciseName":"Pull-up","targetSets":3,"targetReps":"5-8","restSec":120}]},{"name":"W3 · Squat","week":3,"exercises":[{"exerciseName":"Back Squat","targetSets":3,"targetReps":"3","restSec":180,"percents":[80,85,90]},{"exerciseName":"Romanian Deadlift","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Plank","targetSets":3,"targetReps":"30-45s","restSec":60}]},{"name":"W3 · Bench press","week":3,"exercises":[{"exerciseName":"Barbell Bench Press","targetSets":3,"targetReps":"3","restSec":180,"percents":[80,85,90]},{"exerciseName":"Barbell Row","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Face Pull","targetSets":3,"targetReps":"15-20","restSec":60}]},{"name":"W3 · Deadlift","week":3,"exercises":[{"exerciseName":"Deadlift","targetSets":3,"targetReps":"3","restSec":210,"percents":[80,85,90]},{"exerciseName":"Overhead Press","targetSets":3,"targetReps":"3","restSec":180,"percents":[80,85,90]},{"exerciseName":"Pull-up","targetSets":3,"targetReps":"5-8","restSec":120}]},{"name":"W4 · Squat (deload)","week":4,"exercises":[{"exerciseName":"Back Squat","targetSets":3,"targetReps":"5","restSec":180,"percents":[60]},{"exerciseName":"Romanian Deadlift","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Plank","targetSets":3,"targetReps":"30-45s","restSec":60}]},{"name":"W4 · Bench press (deload)","week":4,"exercises":[{"exerciseName":"Barbell Bench Press","targetSets":3,"targetReps":"5","restSec":180,"percents":[60]},{"exerciseName":"Barbell Row","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Face Pull","targetSets":3,"targetReps":"15-20","restSec":60}]},{"name":"W4 · Deadlift (deload)","week":4,"exercises":[{"exerciseName":"Deadlift","targetSets":3,"targetReps":"5","restSec":210,"percents":[60]},{"exerciseName":"Overhead Press","targetSets":3,"targetReps":"5","restSec":180,"percents":[60]},{"exerciseName":"Pull-up","targetSets":3,"targetReps":"5-8","restSec":120}]}]'::jsonb, true, 140, 'en'
WHERE NOT EXISTS (SELECT 1 FROM program_templates WHERE name = 'Strength Waves (% of 1RM)' AND locale = 'en');

INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
SELECT 'Kraftwellen (% vom 1RM)', 'Vier Wochen mit den drei Grundübungen, Lasten in Prozent Ihres geschätzten 1RM: von 70-80 % bis 80-90 %, dann eine Entlastungswoche bei 60 %. Danach mit höherem 1RM neu beginnen.', 'strength', 'intermediate', 3, false, '[{"name":"W1 · Kniebeuge","week":1,"exercises":[{"exerciseName":"Back Squat","targetSets":3,"targetReps":"5","restSec":180,"percents":[70,75,80]},{"exerciseName":"Romanian Deadlift","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Plank","targetSets":3,"targetReps":"30-45s","restSec":60}]},{"name":"W1 · Bankdrücken","week":1,"exercises":[{"exerciseName":"Barbell Bench Press","targetSets":3,"targetReps":"5","restSec":180,"percents":[70,75,80]},{"exerciseName":"Barbell Row","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Face Pull","targetSets":3,"targetReps":"15-20","restSec":60}]},{"name":"W1 · Kreuzheben","week":1,"exercises":[{"exerciseName":"Deadlift","targetSets":3,"targetReps":"5","restSec":210,"percents":[70,75,80]},{"exerciseName":"Overhead Press","targetSets":3,"targetReps":"5","restSec":180,"percents":[70,75,80]},{"exerciseName":"Pull-up","targetSets":3,"targetReps":"5-8","restSec":120}]},{"name":"W2 · Kniebeuge","week":2,"exercises":[{"exerciseName":"Back Squat","targetSets":3,"targetReps":"4","restSec":180,"percents":[75,80,85]},{"exerciseName":"Romanian Deadlift","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Plank","targetSets":3,"targetReps":"30-45s","restSec":60}]},{"name":"W2 · Bankdrücken","week":2,"exercises":[{"exerciseName":"Barbell Bench Press","targetSets":3,"targetReps":"4","restSec":180,"percents":[75,80,85]},{"exerciseName":"Barbell Row","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Face Pull","targetSets":3,"targetReps":"15-20","restSec":60}]},{"name":"W2 · Kreuzheben","week":2,"exercises":[{"exerciseName":"Deadlift","targetSets":3,"targetReps":"4","restSec":210,"percents":[75,80,85]},{"exerciseName":"Overhead Press","targetSets":3,"targetReps":"4","restSec":180,"percents":[75,80,85]},{"exerciseName":"Pull-up","targetSets":3,"targetReps":"5-8","restSec":120}]},{"name":"W3 · Kniebeuge","week":3,"exercises":[{"exerciseName":"Back Squat","targetSets":3,"targetReps":"3","restSec":180,"percents":[80,85,90]},{"exerciseName":"Romanian Deadlift","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Plank","targetSets":3,"targetReps":"30-45s","restSec":60}]},{"name":"W3 · Bankdrücken","week":3,"exercises":[{"exerciseName":"Barbell Bench Press","targetSets":3,"targetReps":"3","restSec":180,"percents":[80,85,90]},{"exerciseName":"Barbell Row","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Face Pull","targetSets":3,"targetReps":"15-20","restSec":60}]},{"name":"W3 · Kreuzheben","week":3,"exercises":[{"exerciseName":"Deadlift","targetSets":3,"targetReps":"3","restSec":210,"percents":[80,85,90]},{"exerciseName":"Overhead Press","targetSets":3,"targetReps":"3","restSec":180,"percents":[80,85,90]},{"exerciseName":"Pull-up","targetSets":3,"targetReps":"5-8","restSec":120}]},{"name":"W4 · Kniebeuge (Entlastung)","week":4,"exercises":[{"exerciseName":"Back Squat","targetSets":3,"targetReps":"5","restSec":180,"percents":[60]},{"exerciseName":"Romanian Deadlift","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Plank","targetSets":3,"targetReps":"30-45s","restSec":60}]},{"name":"W4 · Bankdrücken (Entlastung)","week":4,"exercises":[{"exerciseName":"Barbell Bench Press","targetSets":3,"targetReps":"5","restSec":180,"percents":[60]},{"exerciseName":"Barbell Row","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Face Pull","targetSets":3,"targetReps":"15-20","restSec":60}]},{"name":"W4 · Kreuzheben (Entlastung)","week":4,"exercises":[{"exerciseName":"Deadlift","targetSets":3,"targetReps":"5","restSec":210,"percents":[60]},{"exerciseName":"Overhead Press","targetSets":3,"targetReps":"5","restSec":180,"percents":[60]},{"exerciseName":"Pull-up","targetSets":3,"targetReps":"5-8","restSec":120}]}]'::jsonb, true, 140, 'de'
WHERE NOT EXISTS (SELECT 1 FROM program_templates WHERE name = 'Kraftwellen (% vom 1RM)' AND locale = 'de');

COMMIT;
